window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["bugatti"]={html:"<div class=\"own-bugatti\">\n  <header class=\"nav\">\n    <button class=\"nav-menu\" type=\"button\" aria-expanded=\"false\">Menu</button>\n    <a class=\"wordmark\" href=\"#top\" aria-label=\"Northwind home\">NORTHWIND</a>\n    <a class=\"nav-store\" href=\"#\">Store<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M6 8h12l-1 12H7z\"/><path d=\"M9 8a3 3 0 0 1 6 0\"/></svg></a>\n  </header>\n\n  <section class=\"hero\" id=\"top\" aria-labelledby=\"heroH\">\n    <div class=\"hero-photo\" aria-hidden=\"true\">\n      <svg class=\"hero-car\" viewBox=\"0 0 1000 320\" preserveAspectRatio=\"xMidYMax slice\">\n        <defs>\n          <linearGradient id=\"gcar\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n            <stop offset=\"0\" stop-color=\"#242424\"/><stop offset=\".6\" stop-color=\"#0c0c0c\"/><stop offset=\"1\" stop-color=\"#020202\"/>\n          </linearGradient>\n        </defs>\n        <ellipse cx=\"500\" cy=\"40\" rx=\"460\" ry=\"90\" fill=\"#ffffff\" opacity=\".05\"/>\n        <path d=\"M180 244c18-40 56-82 116-100 96-30 330-32 420 6 50 20 76 50 92 94z\" fill=\"url(#gcar)\"/>\n        <path d=\"M360 156c44-24 132-32 208-22 50 6 82 20 106 42-104-4-232-6-314-20z\" fill=\"#050505\"/>\n        <path d=\"M150 244h712\" stroke=\"#3a3a3a\" stroke-width=\"1.5\"/>\n        <circle cx=\"312\" cy=\"246\" r=\"40\" fill=\"#050505\" stroke=\"#2a2a2a\" stroke-width=\"2.5\"/>\n        <circle cx=\"700\" cy=\"246\" r=\"40\" fill=\"#050505\" stroke=\"#2a2a2a\" stroke-width=\"2.5\"/>\n      </svg>\n      <span class=\"hero-glow\"></span>\n    </div>\n    <div class=\"hero-copy\">\n      <p class=\"caption\">Operations analytics · Since 1998</p>\n      <h1 id=\"heroH\">THE QUIETEST<br>MACHINE ROOM.</h1>\n      <p class=\"caption hero-note\">Precision telemetry for regional operations</p>\n      <a class=\"btn-pill\" href=\"#models\">Discover Northwind</a>\n    </div>\n    <aside class=\"callout\">\n      <div class=\"callout-thumb\" aria-hidden=\"true\"></div>\n      <p>Are you ready for a new kind of operations review?</p>\n      <a class=\"caption-link\" href=\"#careers\">Explore our opportunities</a>\n    </aside>\n  </section>\n\n  <section class=\"models\" id=\"models\" aria-labelledby=\"modelsH\">\n    <div class=\"wrap\">\n      <p class=\"caption center\">The lineup</p>\n      <h2 id=\"modelsH\" class=\"display-lg center\">MODEL SHOWCASE</h2>\n      <div class=\"model-grid\">\n        <article class=\"model\">\n          <div class=\"model-img ph-1\" aria-hidden=\"true\"></div>\n          <h3 class=\"display-md\">Northwind Opus</h3>\n          <p class=\"caption\">16.4M events / hour · single region</p>\n          <a class=\"text-link\" href=\"#\">Discover</a>\n        </article>\n        <article class=\"model\">\n          <div class=\"model-img ph-2\" aria-hidden=\"true\"></div>\n          <h3 class=\"display-md\">Northwind Centodieci</h3>\n          <p class=\"caption\">Federated grid · 18 data planes</p>\n          <a class=\"text-link\" href=\"#\">Discover</a>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"specs\" aria-label=\"Platform specifications\">\n    <div class=\"wrap spec-grid\">\n      <div class=\"spec\"><span class=\"caption\">Throughput</span><b class=\"display-md\">6M/min</b></div>\n      <div class=\"spec\"><span class=\"caption\">Regions</span><b class=\"display-md\">41</b></div>\n      <div class=\"spec\"><span class=\"caption\">Latency p50</span><b class=\"display-md\">0.6s</b></div>\n      <div class=\"spec\"><span class=\"caption\">Uptime</span><b class=\"display-md\">99.99%</b></div>\n    </div>\n  </section>\n\n  <section class=\"newsroom\" aria-labelledby=\"newsH\">\n    <div class=\"wrap\">\n      <p class=\"caption center\">Newsroom</p>\n      <h2 id=\"newsH\" class=\"display-lg center\">LATEST</h2>\n      <div class=\"news-grid\">\n        <article class=\"article\">\n          <div class=\"article-img ph-3\" aria-hidden=\"true\"></div>\n          <p class=\"caption date\">12. NOVEMBER 2025</p>\n          <h3 class=\"title-md\">The operations grid, rebuilt for the edge</h3>\n          <p class=\"body\">A new ingestion architecture keeps every regional pipeline in lockstep without a single lost event.</p>\n          <a class=\"text-link\" href=\"#\">Read</a>\n        </article>\n        <article class=\"article\">\n          <div class=\"article-img ph-4\" aria-hidden=\"true\"></div>\n          <p class=\"caption date\">28. OCTOBER 2025</p>\n          <h3 class=\"title-md\">Why dashboards should arrive early</h3>\n          <p class=\"body\">Predictive thresholds tuned on years of telemetry now warn your team before throughput slips.</p>\n          <a class=\"text-link\" href=\"#\">Read</a>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"careers\" id=\"careers\" aria-labelledby=\"careersH\">\n    <div class=\"wrap\">\n      <p class=\"caption center\">Careers</p>\n      <h2 id=\"careersH\" class=\"display-lg center\">JOIN THE ATELIER</h2>\n      <div class=\"listing\" role=\"list\">\n        <a class=\"row\" href=\"#\" role=\"listitem\"><span class=\"title-md\">Senior Data Engineer</span><span class=\"caption\">Molsheim · Engineering</span><span class=\"chev\" aria-hidden=\"true\">&rarr;</span></a>\n        <a class=\"row\" href=\"#\" role=\"listitem\"><span class=\"title-md\">Operations Analyst</span><span class=\"caption\">Remote · Analytics</span><span class=\"chev\" aria-hidden=\"true\">&rarr;</span></a>\n        <a class=\"row\" href=\"#\" role=\"listitem\"><span class=\"title-md\">Platform Reliability Lead</span><span class=\"caption\">Singapore · Infrastructure</span><span class=\"chev\" aria-hidden=\"true\">&rarr;</span></a>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"cta\">\n    <div class=\"cta-photo\" aria-hidden=\"true\"></div>\n    <div class=\"cta-inner\">\n      <h2 class=\"display-md\">DISCOVER NORTHWIND</h2>\n      <a class=\"btn-pill\" href=\"#\">Request a private demonstration</a>\n    </div>\n  </section>\n\n  <footer class=\"foot\">\n    <div class=\"wrap\">\n      <div class=\"foot-cols\">\n        <div class=\"foot-col\"><p class=\"caption\">Northwind</p><a href=\"#\">Models</a><a href=\"#\">Technology</a><a href=\"#\">Configurator</a></div>\n        <div class=\"foot-col\"><p class=\"caption\">Analytics</p><a href=\"#\">Dashboards</a><a href=\"#\">Streaming</a><a href=\"#\">Alerts</a></div>\n        <div class=\"foot-col\"><p class=\"caption\">Heritage</p><a href=\"#\">Story</a><a href=\"#\">Newsroom</a><a href=\"#\">Careers</a></div>\n        <div class=\"foot-col\"><p class=\"caption\">Connect</p><a href=\"#\">Contact</a><a href=\"#\">Support</a><a href=\"#\">Status</a></div>\n      </div>\n      <p class=\"foot-mark\">NORTHWIND</p>\n      <p class=\"body foot-legal\">Northwind is a fictional product. Sample data — showcase only.</p>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — own layout in the Bugatti design language ═══════════════\n   Scoped under .own-bugatti. Tokens from design-md/bugatti/DESIGN.md. Pure\n   black canvas, three-family trinity (Display uppercase / Text serif body /\n   Monospace for buttons+captions+nav), wide letter-spacing, transparent pill\n   buttons, 0px radius everywhere else, photography as the only depth. */\n\n.own-bugatti {\n  --canvas: #000000;\n  --surface-soft: #0d0d0d;\n  --surface-card: #141414;\n  --surface-elevated: #1f1f1f;\n  --hairline: #262626;\n  --hairline-strong: #3a3a3a;\n  --ink: #ffffff;\n  --body: #cccccc;\n  --body-strong: #e6e6e6;\n  --muted: #999999;\n  --muted-soft: #666666;\n  --link: #c3d9f3;\n\n  --display: \"Bugatti Display\", \"Saira Condensed\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n  --text: \"Bugatti Text Regular\", \"Cormorant Garamond\", Garamond, \"Times New Roman\", serif;\n  --mono: \"Bugatti Monospace\", \"JetBrains Mono\", ui-monospace, \"SF Mono\", monospace;\n\n  --gut: clamp(20px, 5cqi, 64px);\n  --section: clamp(64px, 10cqi, 120px);\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--text);\n  font-size: 16px;\n  font-weight: 400;\n  line-height: 1.5;\n  text-align: left;\n  -webkit-font-smoothing: antialiased;\n}\n.own-bugatti *,\n.own-bugatti *::before,\n.own-bugatti *::after { box-sizing: border-box; }\n.own-bugatti :focus-visible { outline: 1px solid var(--ink); outline-offset: 4px; }\n.own-bugatti a { color: inherit; text-decoration: none; }\n.own-bugatti .wrap { max-width: 1280px; margin: 0 auto; padding: 0 var(--gut); }\n.own-bugatti .center { text-align: center; }\n\n/* ── type ─────────────────────────────────────────────────────────────── */\n.own-bugatti .display-lg {\n  font-family: var(--display); font-weight: 400; text-transform: uppercase;\n  font-size: clamp(34px, 5cqi, 48px); line-height: 1.15; letter-spacing: 3px; margin: 0;\n}\n.own-bugatti .display-md {\n  font-family: var(--display); font-weight: 400; text-transform: uppercase;\n  font-size: clamp(24px, 3cqi, 32px); line-height: 1.2; letter-spacing: 2px; margin: 0;\n}\n.own-bugatti .title-md {\n  font-family: var(--display); font-weight: 400; font-size: 20px; line-height: 1.3; letter-spacing: 1px; margin: 0;\n}\n.own-bugatti .caption {\n  font-family: var(--mono); font-weight: 400; font-size: 11px; line-height: 1.4;\n  letter-spacing: 2px; text-transform: uppercase; color: var(--muted); margin: 0;\n}\n.own-bugatti .body { font-family: var(--text); font-size: 16px; line-height: 1.5; color: var(--body); }\n\n/* ── buttons / links ─────────────────────────────────────────────────── */\n.own-bugatti .btn-pill {\n  display: inline-flex; align-items: center; justify-content: center;\n  height: 44px; padding: 0 32px; border-radius: 9999px;\n  background: transparent; color: var(--ink); border: 1px solid var(--ink);\n  font-family: var(--mono); font-weight: 400; font-size: 14px; letter-spacing: 2.5px;\n  text-transform: uppercase; transition: background-color .3s ease, color .3s ease;\n}\n.own-bugatti .btn-pill:hover { background: var(--ink); color: var(--canvas); }\n.own-bugatti .text-link {\n  display: inline-block; color: var(--link); font-family: var(--text); font-size: 15px;\n  text-decoration: underline; text-underline-offset: 4px;\n}\n.own-bugatti .caption-link {\n  font-family: var(--mono); font-size: 11px; letter-spacing: 2px; text-transform: uppercase;\n  color: var(--ink); border-bottom: 1px solid var(--hairline-strong); padding-bottom: 3px;\n}\n\n/* ── nav ──────────────────────────────────────────────────────────────── */\n.own-bugatti .nav {\n  position: absolute; top: 0; left: 0; right: 0; z-index: 20;\n  height: 56px; display: flex; align-items: center; justify-content: space-between;\n  padding: 0 var(--gut); background: transparent;\n}\n.own-bugatti .nav-menu {\n  background: none; border: 0; cursor: pointer; color: var(--ink);\n  font-family: var(--mono); font-size: 12px; letter-spacing: 2px; text-transform: uppercase; padding: 8px 0;\n}\n.own-bugatti .wordmark {\n  font-family: var(--display); font-weight: 400; font-size: 14px; letter-spacing: 6px;\n  text-transform: uppercase; color: var(--ink);\n}\n.own-bugatti .nav-store {\n  display: inline-flex; align-items: center; gap: 8px; color: var(--ink);\n  font-family: var(--mono); font-size: 12px; letter-spacing: 2px; text-transform: uppercase;\n}\n.own-bugatti .nav-store svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.3; stroke-linecap: round; stroke-linejoin: round; }\n\n/* ── hero ─────────────────────────────────────────────────────────────── */\n.own-bugatti .hero {\n  position: relative; isolation: isolate; overflow: hidden;\n  min-height: min(720px, 88cqi);\n  display: grid; place-items: center; text-align: center;\n  padding: clamp(120px, 18cqi, 200px) var(--gut) clamp(80px, 10cqi, 130px);\n}\n.own-bugatti .hero-photo { position: absolute; inset: 0; z-index: -2; background: radial-gradient(130% 100% at 50% 0%, #1b1b1b 0%, #080808 55%, #000 100%); }\n.own-bugatti .hero-car { position: absolute; left: 50%; bottom: 6%; width: min(1000px, 96%); transform: translateX(-50%); opacity: .9; }\n.own-bugatti .hero-glow { position: absolute; inset: 0; background: linear-gradient(0deg, rgba(0,0,0,.85) 0%, transparent 55%); }\n.own-bugatti .hero-copy { position: relative; z-index: 1; max-width: 900px; }\n.own-bugatti .hero h1 {\n  font-family: var(--display); font-weight: 400; text-transform: uppercase;\n  font-size: clamp(38px, 6.4cqi, 64px); line-height: 1.1; letter-spacing: 4px; margin: 22px 0 18px;\n}\n.own-bugatti .hero-note { color: var(--body); margin-bottom: 40px; }\n.own-bugatti .callout {\n  position: absolute; right: var(--gut); bottom: clamp(32px, 6cqi, 72px); z-index: 2;\n  width: 320px; max-width: 78cqi; text-align: left;\n  background: var(--surface-card); padding: 16px;\n}\n.own-bugatti .callout-thumb { height: 0; padding-bottom: 46%; margin-bottom: 14px; background: radial-gradient(120% 120% at 60% 20%, #232323, #0a0a0a), linear-gradient(90deg, #101010, #222); }\n.own-bugatti .callout p { font-family: var(--text); font-size: 14px; color: var(--body-strong); margin: 0 0 12px; }\n\n/* ── models ──────────────────────────────────────────────────────────── */\n.own-bugatti .models { padding: var(--section) 0; }\n.own-bugatti .models .display-lg { margin: 16px 0 48px; }\n.own-bugatti .model-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; }\n.own-bugatti .model { display: flex; flex-direction: column; }\n.own-bugatti .model-img { height: 0; padding-bottom: 50%; margin-bottom: 24px; position: relative; overflow: hidden; }\n.own-bugatti .model-img::after { content: \"\"; position: absolute; inset: 0; background: linear-gradient(160deg, rgba(255,255,255,.05), transparent 55%); }\n.own-bugatti .ph-1 { background-image: radial-gradient(110% 90% at 60% 20%, #262626, #060606); }\n.own-bugatti .ph-2 { background-image: radial-gradient(110% 90% at 40% 25%, #1c1c1c, #050505); }\n.own-bugatti .model .display-md { margin-bottom: 10px; }\n.own-bugatti .model .caption { margin-bottom: 16px; }\n.own-bugatti .model .text-link { margin-top: auto; }\n\n/* ── specs ───────────────────────────────────────────────────────────── */\n.own-bugatti .specs { padding: calc(var(--section) / 2) 0; }\n.own-bugatti .spec-grid { display: grid; grid-template-columns: repeat(4, 1fr); border-top: 1px solid var(--hairline); border-bottom: 1px solid var(--hairline); }\n.own-bugatti .spec { padding: 32px 24px; border-right: 1px solid var(--hairline); }\n.own-bugatti .spec:last-child { border-right: 0; }\n.own-bugatti .spec .caption { display: block; margin-bottom: 12px; }\n.own-bugatti .spec b { color: var(--ink); }\n\n/* ── newsroom ────────────────────────────────────────────────────────── */\n.own-bugatti .newsroom { padding: var(--section) 0; }\n.own-bugatti .newsroom .display-lg { margin: 16px 0 48px; }\n.own-bugatti .news-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; }\n.own-bugatti .article { background: var(--canvas); border: 1px solid var(--hairline); padding: 24px; display: flex; flex-direction: column; }\n.own-bugatti .article-img { height: 0; padding-bottom: 56.25%; margin-bottom: 20px; position: relative; overflow: hidden; }\n.own-bugatti .ph-3 { background-image: radial-gradient(120% 90% at 55% 20%, #212121, #070707); }\n.own-bugatti .ph-4 { background-image: radial-gradient(110% 90% at 40% 30%, #1a1a1a, #060606); }\n.own-bugatti .article .date { margin-bottom: 14px; }\n.own-bugatti .article .title-md { margin-bottom: 12px; }\n.own-bugatti .article .body { margin: 0 0 20px; }\n.own-bugatti .article .text-link { margin-top: auto; }\n\n/* ── careers ─────────────────────────────────────────────────────────── */\n.own-bugatti .careers { padding: var(--section) 0; }\n.own-bugatti .careers .display-lg { margin: 16px 0 40px; }\n.own-bugatti .listing { display: flex; flex-direction: column; }\n.own-bugatti .row {\n  display: grid; grid-template-columns: 1fr auto auto; align-items: center; gap: 24px;\n  padding: 24px 0; border-bottom: 1px solid var(--hairline); transition: padding-left .3s ease;\n}\n.own-bugatti .row:first-child { border-top: 1px solid var(--hairline); }\n.own-bugatti .row:hover { padding-left: 14px; }\n.own-bugatti .row .caption { color: var(--muted); }\n.own-bugatti .chev { color: var(--muted); transition: transform .3s ease, color .3s ease; }\n.own-bugatti .row:hover .chev { color: var(--ink); transform: translateX(5px); }\n\n/* ── CTA ─────────────────────────────────────────────────────────────── */\n.own-bugatti .cta { position: relative; isolation: isolate; overflow: hidden; padding: clamp(64px, 8cqi, 80px) var(--gut); text-align: center; }\n.own-bugatti .cta-photo { position: absolute; inset: 0; z-index: -2; background: radial-gradient(120% 130% at 50% 120%, #1e1e1e 0%, #0a0a0a 55%, #000 100%); }\n.own-bugatti .cta-inner { max-width: 720px; margin: 0 auto; }\n.own-bugatti .cta .display-md { margin-bottom: 28px; }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-bugatti .foot { padding: clamp(48px, 6cqi, 64px) 0 40px; border-top: 1px solid var(--hairline); }\n.own-bugatti .foot-cols { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }\n.own-bugatti .foot-col { display: flex; flex-direction: column; gap: 12px; }\n.own-bugatti .foot-col .caption { color: var(--ink); margin-bottom: 4px; }\n.own-bugatti .foot-col a { font-family: var(--text); font-size: 14px; color: var(--muted); }\n.own-bugatti .foot-col a:hover { color: var(--ink); }\n.own-bugatti .foot-mark { font-family: var(--display); font-size: 14px; letter-spacing: 6px; text-align: center; color: var(--body); margin: 48px 0 0; }\n.own-bugatti .foot-legal { text-align: center; font-size: 14px; color: var(--muted-soft); margin: 16px 0 0; }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-bugatti .callout { display: none; }\n  .own-bugatti .spec-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-bugatti .spec:nth-child(2) { border-right: 0; }\n  .own-bugatti .spec:nth-child(1), .own-bugatti .spec:nth-child(2) { border-bottom: 1px solid var(--hairline); }\n}\n@container frame (max-width: 760px) {\n  .own-bugatti .model-grid, .own-bugatti .news-grid, .own-bugatti .foot-cols { grid-template-columns: 1fr; }\n  .own-bugatti .hero { min-height: 78cqi; }\n  .own-bugatti .hero h1 { letter-spacing: 2px; }\n  .own-bugatti .spec-grid { grid-template-columns: 1fr; }\n  .own-bugatti .spec { border-right: 0; border-bottom: 1px solid var(--hairline); }\n  .own-bugatti .spec:last-child { border-bottom: 0; }\n  .own-bugatti .foot-cols { gap: 32px; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-bugatti *, .own-bugatti *::before, .own-bugatti *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — own-layout behaviour for showcase.html ══════════════════
   Bugatti's surface is static; the menu button announces press state and
   closes on Escape. Query only inside root, clean up on unmount. */
(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  window.OWN_LAYOUTS['bugatti'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;

      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }

      var menu = root.querySelector('.nav-menu');
      on(menu, 'click', function () {
        var open = menu.getAttribute('aria-expanded') === 'true';
        menu.setAttribute('aria-expanded', String(!open));
        menu.style.letterSpacing = open ? '' : '3px';
      });
      on(document, 'keydown', function (e) {
        if (e.key === 'Escape' && menu) menu.setAttribute('aria-expanded', 'false');
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        if (menu) menu.setAttribute('aria-expanded', 'false');
      };
    }
  };
})();
